{"implementation": "def solve(case):
    edges = case['edges']
    refinement = case['refinement']
    group_nodes = {}
    for node, grp in refinement.items():
        group_nodes.setdefault(grp, []).append(node)
    members = {grp: sorted(nodes) for grp, nodes in group_nodes.items()}
    agg = {}
    for u, v, w in edges:
        gu = refinement[u]
        gv = refinement[v]
        key = tuple(sorted([gu, gv]))
        agg[key] = agg.get(key, 0) + w
    sorted_keys = sorted(agg.keys())
    aggregate_edges = [[k[0], k[1], agg[k]] for k in sorted_keys]
    return {'aggregate_edges': aggregate_edges, 'members': members}"}
